source('code/analysis/main/engine.R')
ip<-read_csv(file.path(OUT,'intensity_matched_pairs.csv'),show_col_types=FALSE);pa<-bind_rows(pairs,ip);a<-list()
raw_first<-x$raw%>%filter(valid_tract,str_trim(type)=='1',!is.na(pis_year),!pis_year%in%c(8888,9999))%>%transmute(tract_id=as.numeric(tract_digits),pis_year)%>%group_by(tract_id)%>%summarise(raw_first=min(pis_year),.groups='drop')
z<-p%>%distinct(tract_id,first_pis_year)%>%left_join(raw_first,by='tract_id');stopifnot(all((is.na(z$first_pis_year)&is.na(z$raw_first))|(!is.na(z$first_pis_year)&!is.na(z$raw_first)&z$first_pis_year==z$raw_first)))
for(gr in unique(pa$group))for(g in 2011:2019){
 pp<-pa%>%filter(group==gr,cohort==g);pg<-if(gr=='pooled')p else if(gr%in%c('lower_income','higher_income'))filter(p,income_group==gr) else filter(p,is_control|intensity_group==gr)
 growth<-c(if(g>=2012)paste0(c('log_rac','log_wac','log_seer_pop','rac_total','wac_total'),'_recent'),if(g>=2015)paste0(c('log_rac','log_wac','log_seer_pop','rac_total','wac_total'),'_early'))
 cv<-c(x$match_covars_full,growth);core<-c('log_seer_pop','log_rac','log_wac',growth)
 e<-pg%>%filter(year==g-1,residential_eligible,min_pre_population>=100,is_control|first_pis_year==g)%>%filter(if_all(all_of(cv),is.finite))
 stopifnot(all(pp$tract_id%in%e$tract_id),!anyDuplicated(pp$tract_id[pp$treated_cohort==0]),all(is.na(pp$first_pis_year[pp$treated_cohort==0])|pp$first_pis_year[pp$treated_cohort==0]>2019))
 tr<-filter(e,first_pis_year==g);sdT<-sapply(tr[,core],sd);sdT<-pmax(sdT,1e-10)
 t<-pp%>%filter(treated_cohort==1)%>%select(match_id,tract_id)%>%left_join(e,by='tract_id')%>%arrange(match_id)
 c<-pp%>%filter(treated_cohort==0)%>%select(match_id,tract_id)%>%left_join(e,by='tract_id')%>%arrange(match_id)
 stopifnot(identical(t$match_id,c$match_id),all(t$statea==c$statea),all(t$first_pis_year==g))
 mx<-max(abs(sweep(as.matrix(t[,core])-as.matrix(c[,core]),2,sdT,'/')))
 pop<-max(exp(abs(t$log_seer_pop-c$log_seer_pop)));rac<-max(exp(abs(t$log_rac-c$log_rac)));wac<-max(exp(abs(t$log_wac-c$log_wac)))
 stopifnot(mx<=1+1e-8,pop<=3+1e-8,rac<=5+1e-8,wac<=5+1e-8)
 a[[paste(gr,g)]]<-tibble(group=gr,cohort=g,pairs=nrow(t),max_standardized_difference=mx,max_population_ratio=pop,max_rac_ratio=rac,max_wac_ratio=wac)
}
write_csv(bind_rows(a),file.path(OUT,'matching_constraint_validation.csv'));writeLines('PASS: raw TYPE 1 dates reconciled; never-treated retained; no pre-2011-treated; all pairs same-state; eligibility, all 1 SD core bounds and scale bounds verified independently.',file.path(OUT,'DESIGN_VALIDATION.txt'))
